{
  "name": "reweight_gap_combined",
  "intuition": "This preference builder combines the pairwise gap signal with instance-level normalization to create a robust, instance-conditioned weight. By multiplying the raw gap with the normalized instance objective scale, it emphasizes pairs with significant cost differences relative to each instance's variability, while maintaining non-negativity and a simple clamp for stability. This approach leverages the strengths of both parents: the gap-based signal and instance-aware modulation, ensuring the weights are both meaningful and numerically stable across varying instance scales.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["ops.mul", "ops.clamp", "ops.abs", "ops.ones_like"],
  "implementation_hint": {
    "expects": ["objective", "instance_obj_mad"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    instance_obj_scale = feature_cache['instance_obj_mad']\n    eps = 1e-6\n    # Pairwise cost difference\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Modulate by instance scale\n    scale = ops.clamp(instance_obj_scale[b_idx], min=eps)\n    raw_weight = gap * (1.0 / scale)\n    # Ensure non-negativity and stability\n    weight = ops.clamp(raw_weight, min=0.0, max=float('inf'))\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_gap_combined', 'weight_family': 'gap_linear'})"
}

