{
  "name": "builder_all_pairs_gap_linear_instance_cond_010",
  "intuition": "all pairs geometry with gap-linear weighting modulated by instance_obj_range and instance_log_prob_range to emphasize pairs with large normalized gaps and uncertainty",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_linear"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "instance_obj_range",
      "instance_log_prob_range"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    eps = 1e-6\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    instance_obj_range = feature_cache['instance_obj_range']\n    instance_log_prob_range = feature_cache['instance_log_prob_range']\n    gap_scaled = gap / instance_obj_range[b_idx].clamp_min(eps)\n    log_prob_range_scaled = instance_log_prob_range[b_idx].clamp_min(eps)\n    beta = float(extra.get('beta', 1.0))\n    weight_raw = gap_scaled * (1.0 + beta * log_prob_range_scaled)\n    weight_raw = weight_raw.clamp_min(0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = weight_raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n"
}

{
  "name": "builder_all_pairs_gap_rank_blend_010",
  "intuition": "reweight all pairs by blending gap magnitude with rank span, normalized by instance-level statistics",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_rank_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_rank_blend"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "rank",
      "instance_obj_mad",
      "instance_log_prob_std"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    eps = 1e-6\n    instance_obj_mad = feature_cache['instance_obj_mad'].clamp_min(eps)\n    instance_log_prob_std = feature_cache['instance_log_prob_std'].clamp_min(eps)\n    gap_scaled = gap / instance_obj_mad[b_idx]\n    rank_span = rank[b_idx, loser_idx] - rank[b_idx, winner_idx]\n    beta = float(extra.get('beta', 3.0))\n    gamma = float(extra.get('gamma', 1.0))\n    margin_abs = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    margin_scaled = margin_abs / instance_log_prob_std[b_idx]\n    raw = (gap_scaled.clamp_min(0.0) ** gamma) * torch.sigmoid(beta * rank_span) / (margin_scaled + eps)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n"
}

{
  "name": "paired_weight_gap_bandpass",
  "intuition": "This crossover combines the instance-conditioned gap linear signal with a bandpass clamping to enhance robustness against outliers and scale variations, leveraging the complementary strengths of margin-based and frequency-bounded weighting ideas. It maintains the fixed pair topology for stable comparison and introduces a non-linear bandpass filter to control weight distribution.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_bandpass",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "gap_linear", "clamp"],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "instance_obj_mad",
      "instance_log_prob_std"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    b_idx, winner_idx, loser_idx = (objective[:, :, None] < objective[:, None, :]).nonzero(as_tuple=True)\n    # Compute gap scaled by instance MAD\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    instance_obj_mad = feature_cache['instance_obj_mad']\n    eps = 1e-6\n    scaled_gap = gap / instance_obj_mad[b_idx].clamp_min(eps)\n    # Apply bandpass filter with instance std to control weight bounds\n    instance_log_prob_std = feature_cache['instance_log_prob_std']\n    # Construct raw weight from scaled gap\n    raw_weight = scaled_gap\n    # Bandpass: clamp between 0.25 and 4.0, scaled by a sigmoid to smooth edges\n    bandpass_mask = (raw_weight >= 0.25) & (raw_weight <= 4.0)\n    weight = torch.where(bandpass_mask, raw_weight, torch.full_like(raw_weight, 0.25))\n    weight = torch.clamp(weight, 0.25, 4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'paired_weight_gap_bandpass', 'weight_family': 'gap_bandpass'})"
}

