  "name": "all_pairs_gap_bandpass_simplified_001",
  "intuition": "Reweight all pairs using a simple triangular bandpass on normalized gap scaled by instance MAD, avoiding imports and complex margin scaling",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_bandpass",
