  "implementation_hint": {
    "expects": [
      "objective",
      "instance_obj_mad"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    eps = 1e-6\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    instance_scale = feature_cache['instance_obj_mad'].clamp_min(eps)\n    gap_norm = gap / instance_scale[b_idx]\n    lower = float(extra.get('bandpass_lower', 0.5))\n    upper = float(extra.get('bandpass_upper', 2.0))\n    weight = gap_norm.new_zeros(gap_norm.shape)\n    in_band = (gap_norm >= lower) & (gap_norm <= upper)\n    mid = (lower + upper) * 0.5\n    half_width = (upper - lower) * 0.5 + eps\n    weight[in_band] = 1.0 - (gap_norm[in_band] - mid).abs() / half_width\n    clamp_lo = 0.1\n    clamp_hi = 3.0\n    weight = weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})"
